package com.yonlab.vision;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.*;import android.text.InputFilter;import android.view.*;import android.widget.*;
import com.google.zxing.NotFoundException;import org.json.*;import java.io.*;import java.lang.ref.WeakReference;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Independent real photo tools; a failure in one engine does not prevent other tools. */
public final class ToolPhotoActivity extends YOnActivity {
 private static final int PICK=801,CAPTURE=501;private static final AtomicLong IDS=new AtomicLong(SystemClock.elapsedRealtimeNanos());private static final ConcurrentHashMap<String,Long> LATEST=new ConcurrentHashMap<>();
 private final Handler main=new Handler(Looper.getMainLooper());private final ThreadPoolExecutor worker=new ThreadPoolExecutor(0,1,1,TimeUnit.SECONDS,new ArrayBlockingQueue<>(1),r->{Thread t=new Thread(r,"YOnPhotoTool");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
 private LinearLayout mediaBody;private FrameLayout previewPanel;private ScrollView controlScroll;
 private String tool;private VisionCanvas canvas;private ToolOverlay overlay;private TextView state,output;private EditText input;private Switch korean;private Uri selected;private String sourceKind="selected",lastAction="";private Job current;private Bitmap displayed;private Uri generated;private boolean destroyed,initialDone;
 static boolean validTool(String value){return LabRoutes.photoTool(value);}
 static String title(String value){return "pet".equals(value)?"반려동물":"ball".equals(value)?"공 탐지":"ocr".equals(value)?"텍스트 읽기":"pose".equals(value)?"자세 분석":"QR · 바코드";}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);String request=getIntent().getStringExtra("tool");tool=validTool(request)?request:"qr";if(saved!=null){String value=saved.getString("uri");if(value!=null)selected=Uri.parse(value);initialDone=saved.getBoolean("initialDone");}else try{selected=ImageIO.imageUri(getIntent());}catch(RuntimeException ignored){}build();if(saved!=null&&input!=null)input.setText(saved.getString("text","AXSL Vision"));}
 private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Ui.BACK);LinearLayout header=Ui.brandHeader(this,title(tool));header.addView(Ui.secondary(this,"닫기",v->finish()),new LinearLayout.LayoutParams(Ui.dp(this,80),-2));root.addView(header);LinearLayout row=mediaBody=new LinearLayout(this);row.setPadding(Ui.dp(this,16),Ui.dp(this,12),Ui.dp(this,16),Ui.dp(this,16));root.addView(row,new LinearLayout.LayoutParams(-1,0,1));FrameLayout preview=previewPanel=new FrameLayout(this);preview.setBackground(Ui.round(this,Ui.NAVY,12));preview.setClipToOutline(true);canvas=new VisionCanvas(this);preview.addView(canvas,new FrameLayout.LayoutParams(-1,-1));overlay=new ToolOverlay(this);preview.addView(overlay,new FrameLayout.LayoutParams(-1,-1));LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,-1,2);left.rightMargin=Ui.dp(this,14);row.addView(preview,left);ScrollView scroll=controlScroll=new ScrollView(this);scroll.setFillViewport(true);row.addView(scroll,new LinearLayout.LayoutParams(0,-1,1));LinearLayout panel=Ui.panel(this);scroll.addView(panel);state=Ui.heading(this,"사진을 선택하세요",21);panel.addView(state);output=Ui.text(this,"",15);output.setTextIsSelectable(true);panel.addView(output);
  panel.addView(Ui.button(this,"사진 선택",v->pick()),space());panel.addView(Ui.secondary(this,"촬영",v->capture()),space());panel.addView(Ui.secondary(this,"다시 분석",v->retry()),space());if("qr".equals(tool)){input=new EditText(this);input.setHint("QR에 담을 내용");input.setText("AXSL Vision");input.setTextColor(Ui.INK);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(500)});panel.addView(input,space());panel.addView(Ui.secondary(this,"QR 생성",v->run("generate")),space());panel.addView(Ui.secondary(this,"QR 이미지 공유",v->share()),space());}else if("ocr".equals(tool)){korean=new Switch(this);korean.setText("한글 읽기");korean.setTextColor(Ui.INK);korean.setChecked(!"mlkit-ocr-latin".equals(getIntent().getStringExtra("model_id")));panel.addView(korean,space());panel.addView(Ui.secondary(this,"예시 문서",v->run("demo")),space());}if("qr".equals(tool)||"ocr".equals(tool))panel.addView(Ui.secondary(this,"내용 복사",v->copy()),space());panel.addView(Ui.secondary(this,"도구 모음",v->{startActivity(new Intent().setClassName(this,"com.yonlab.vision.OneActivity"));finish();}),space());setContentView(root);MediaPanels.arrange(this,mediaBody,previewPanel,controlScroll,1.8f);}
 @Override public void onConfigurationChanged(android.content.res.Configuration configuration){super.onConfigurationChanged(configuration);MediaPanels.arrange(this,mediaBody,previewPanel,controlScroll,1.8f);canvas.invalidate();overlay.invalidate();}
 private LinearLayout.LayoutParams space(){LinearLayout.LayoutParams p=Ui.fill();p.topMargin=Ui.dp(this,10);return p;}
 @Override protected void onResume(){super.onResume();if(!initialDone){initialDone=true;String action=getIntent().getStringExtra("action");if("generate".equals(action)&&"qr".equals(tool)){if(getIntent().hasExtra("text"))input.setText(getIntent().getStringExtra("text"));run("generate");}else if(getIntent().getBooleanExtra("demo",false)&&"ocr".equals(tool))run("demo");else if(selected!=null)run("image");}}
 private void pick(){try{startActivityForResult(OneInputs.picker(this,"image",tool),PICK);}catch(ActivityNotFoundException e){state.setText("사진을 선택할 수 없습니다");}}
 private void capture(){try{startActivityForResult(new Intent().setClassName(this,"com.yonlab.vision.CaptureActivity"),CAPTURE);}catch(ActivityNotFoundException e){state.setText("촬영을 열 수 없습니다");}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if((request!=PICK&&request!=CAPTURE)||result!=RESULT_OK||data==null)return;Uri uri=data.getData();if(uri==null){String value=data.getStringExtra("photo_uri");if(value!=null)uri=Uri.parse(value);}if(uri==null||!"content".equals(uri.getScheme())){state.setText("사진을 열 수 없습니다");return;}selected=uri;sourceKind=request==CAPTURE?"camera":"selected";run("image");}
 private void retry(){if(lastAction.isEmpty()){if(selected!=null)run("image");else state.setText("사진을 선택하세요");}else run(lastAction);}
 private void run(String action){if(destroyed)return;if("demo".equals(action)&&!"ocr".equals(tool)){state.setText("라이브러리에서 실제 사진을 선택하세요");return;}if("image".equals(action)&&selected==null){state.setText("사진을 선택하세요");return;}if("generate".equals(action)&&(!"qr".equals(tool)||input.getText().toString().isEmpty())){state.setText("내용을 입력하세요");return;}if(current!=null)current.canceled.set(true);worker.getQueue().clear();lastAction=action;Job job=new Job(getApplicationContext(),this,tool,action,selected,sourceKind,input==null?"":input.getText().toString(),korean==null||korean.isChecked());current=job;LATEST.put(tool,job.id);state.setText("generate".equals(action)?"QR 생성 중":"분석 중");try{worker.execute(job);}catch(RejectedExecutionException e){state.setText("잠시 후 다시 시도하세요");}}
 private void accept(Job job,Result result){if(destroyed||isFinishing()||isDestroyed()||current!=job||job.canceled.get()){result.discard();return;}current=null;Bitmap previous=displayed;displayed=result.image;canvas.show(displayed,null,result.detections);if(previous!=null&&previous!=displayed&&!previous.isRecycled())previous.recycle();overlay.show(displayed==null?1:displayed.getWidth(),displayed==null?1:displayed.getHeight(),result.boxes,result.points);state.setText(result.heading);output.setText(result.text);generated=result.generated;}
 private void share(){if(generated==null){state.setText("QR을 먼저 생성하세요");return;}try{Intent i=new Intent(Intent.ACTION_SEND).setType("image/png").putExtra(Intent.EXTRA_STREAM,generated).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("QR",generated));startActivity(Intent.createChooser(i,"QR 이미지 공유"));}catch(ActivityNotFoundException e){state.setText("공유 앱을 열 수 없습니다");}}
 private void copy(){String value=output.getText().toString();if(value.isEmpty())return;((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText(title(tool),value));Toast.makeText(this,"복사됨",Toast.LENGTH_SHORT).show();}
 @Override protected void onPause(){if(current!=null){current.canceled.set(true);current=null;state.setText("분석 대기");}super.onPause();}
 @Override protected void onSaveInstanceState(Bundle saved){if(selected!=null)saved.putString("uri",selected.toString());saved.putBoolean("initialDone",initialDone);if(input!=null)saved.putString("text",input.getText().toString());super.onSaveInstanceState(saved);}
 @Override protected void onDestroy(){destroyed=true;if(current!=null)current.canceled.set(true);worker.shutdown();canvas.show(null,null,null);if(displayed!=null&&!displayed.isRecycled())displayed.recycle();displayed=null;super.onDestroy();}
 private static final class Result {Bitmap image;String state="ERROR",heading="분석할 수 없습니다",text="",format="",error="";Uri generated;File generatedFile;List<Observations.Detection> detections=Collections.emptyList();List<PhotoVisionEngine.TextBox> boxes=Collections.emptyList();List<PoseGeometry.Point> points=Collections.emptyList();boolean engineClosed=true;long elapsed;void discard(){if(image!=null&&!image.isRecycled())image.recycle();if(generatedFile!=null)generatedFile.delete();}}
 private static final class Job implements Runnable {
  final long id=IDS.incrementAndGet();final Context app;final WeakReference<ToolPhotoActivity> owner;final String tool,action,source,text,modelId;final Uri uri;final boolean korean;final AtomicBoolean canceled=new AtomicBoolean();
  Job(Context c,ToolPhotoActivity a,String t,String act,Uri u,String src,String value,boolean ko){app=c;owner=new WeakReference<>(a);tool=t;action=act;uri=u;source=src;text=value;korean=ko;modelId=a.getIntent().getStringExtra("model_id");}
  public void run(){Result result=new Result();ObjectEngine objects=null;PhotoVisionEngine vision=null;OnePoseEngine poseModel=null;long started=SystemClock.elapsedRealtime();try{if(canceled.get())return;if("generate".equals(action)){int[] pixels=BarcodeHelper.qr(text,512);result.image=Bitmap.createBitmap(pixels,512,512,Bitmap.Config.ARGB_8888);BarcodeHelper.Decoded decoded=BarcodeHelper.decode(pixels,512,512);if(!text.equals(decoded.text))throw new IOException("QR roundtrip");result.text=decoded.text;result.format=decoded.format;result.heading="QR 생성 완료";result.state="GENERATED";File output=ImageIO.exported(app,"qr-"+UUID.randomUUID()+".png"),pending=new File(output.getAbsolutePath()+".new");try{try(FileOutputStream out=new FileOutputStream(pending)){if(!result.image.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("QR save");out.getFD().sync();}if(canceled.get())throw new IOException("canceled");if(!pending.renameTo(output))throw new IOException("QR commit");result.generatedFile=output;result.generated=ImageIO.uri(app,output);}finally{pending.delete();}}
    else{if("demo".equals(action)){if("ocr".equals(tool))result.image=document();else throw new IOException("demo unavailable");}else result.image=ImageIO.load(app,uri,1600);if(canceled.get())throw new IOException("canceled");
     if("qr".equals(tool)){int w=result.image.getWidth(),h=result.image.getHeight();int[] pixels=new int[w*h];result.image.getPixels(pixels,0,w,0,0,w,h);try{BarcodeHelper.Decoded decoded=BarcodeHelper.decode(pixels,w,h);result.text=decoded.text;result.format=decoded.format;result.heading="코드 읽기 완료";result.state="DECODED";}catch(NotFoundException empty){result.heading="코드를 찾지 못했습니다";result.state="NO_CODE";}}
     else if("pet".equals(tool)||"ball".equals(tool)){result.engineClosed=false;objects=new ObjectEngine(app,"ball".equals(tool));result.detections=ToolFilters.select(objects.analyze(result.image,.4f),tool);result.heading=("pet".equals(tool)?"반려동물 ":"공 ")+result.detections.size()+"개";StringBuilder found=new StringBuilder();for(Observations.Detection d:result.detections){if(found.length()>0)found.append('\n');found.append("cat".equals(d.label)?"고양이":"dog".equals(d.label)?"개":"공").append(" · ").append(String.format(Locale.KOREA,"%.1f%%",d.score*100));}result.text=found.toString();result.state="COMPLETED";}
     else{result.engineClosed=false;if("ocr".equals(tool))vision=new PhotoVisionEngine(tool,korean);else poseModel=new OnePoseEngine("mlkit-pose-accurate".equals(modelId));if("ocr".equals(tool)){PhotoVisionEngine.Ocr found=vision.ocr(result.image);result.text=found.text;result.boxes=found.boxes;result.heading=found.text.isEmpty()?"텍스트를 찾지 못했습니다":"텍스트 읽기 완료";}else{result.points=poseModel.pose(result.image);int visible=PoseGeometry.visible(result.points).size();result.heading=visible==0?"사람을 찾지 못했습니다":"관측 지점 "+visible+"개";result.text=visible==0?"":"자세 분석 완료";}result.state="COMPLETED";}
    }
   }catch(Exception|LinkageError|OutOfMemoryError e){result.state=canceled.get()?"CANCELED":"ERROR";result.error=e.getClass().getSimpleName();result.heading=canceled.get()?"분석 취소":"분석할 수 없습니다";}
   finally{try{if(objects!=null)objects.close();if(vision!=null)vision.close();if(poseModel!=null)poseModel.close();result.engineClosed=true;}catch(Exception|LinkageError e){result.engineClosed=false;result.error=e.getClass().getSimpleName();result.state="ERROR";}result.elapsed=SystemClock.elapsedRealtime()-started;}
   if(canceled.get()){write(result,"CANCELED");result.discard();return;}write(result,result.state);ToolPhotoActivity screen=owner.get();if(screen==null){result.discard();return;}screen.main.post(()->{ToolPhotoActivity a=owner.get();if(a==null)result.discard();else a.accept(this,result);});
  }
  private Bitmap document(){Bitmap image=Bitmap.createBitmap(1200,600,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.drawColor(Color.WHITE);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(Color.BLACK);p.setTextSize(88);p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));canvas.drawText("AXSL Vision",70,140,p);canvas.drawText("HELLO 2026",70,290,p);if(korean)canvas.drawText("안녕하세요",70,440,p);return image;}
  private void write(Result r,String state){Long latest=LATEST.get(tool);if(latest==null||latest!=id)return;try{JSONArray detections=new JSONArray();for(Observations.Detection d:r.detections)detections.put(new JSONObject().put("classId",d.classId).put("label",d.label).put("score",d.score).put("left",d.left).put("top",d.top).put("right",d.right).put("bottom",d.bottom));JSONObject record=new JSONObject().put("runId",id).put("tool",tool).put("modelId",modelId==null?"ocr".equals(tool)?(korean?"mlkit-ocr-ko":"mlkit-ocr-latin"):"pose".equals(tool)?"mlkit-pose":"qr".equals(tool)?"zxing-qr":"ball".equals(tool)?"efficientdet-lite0-ball":"ssd-mobilenet-v1":modelId).put("action",action).put("state",state).put("errorType",r.error).put("source",action.equals("image")?source:action).put("width",r.image==null?0:r.image.getWidth()).put("height",r.image==null?0:r.image.getHeight()).put("engineCloseReturned",r.engineClosed).put("elapsedMs",r.elapsed).put("format",r.format).put("textLength",r.text.length()).put("textSha256",sha(r.text)).put("detections",detections).put("ocrBlocks",r.boxes.size()).put("ocrScript",korean?"Korean":"Latin").put("poseLandmarks",r.points.size()).put("poseVisible",PoseGeometry.visible(r.points).size()).put("networkUpload",false);Records.write(app,"tool-"+tool+"-result.json",record);Records.event(app,"tool-"+tool,state,new JSONObject().put("modelId",record.optString("modelId")).put("feature",tool).put("runId",id).put("elapsedMs",r.elapsed).put("errorType",r.error));}catch(Exception ignored){}}
  private static String sha(String value)throws Exception{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
 }
}
